------------ import ------------
------------ import ------------

------------ define ------------
local GoodNodeMBPath = "Game.Behaviours.GoodNodeMB"
local Days = { 5, 7, 30 } ---特殊的天
------------ define ------------

--- from: Assets/BundleResources/Prefabs/Activity/ActivityEntry.prefab > name: Cell
---@class UIActivityEntryWelfareCellNode
---@field Env                            UIActivityEntryWelfareCellNode
---@field controller                        Engine.Modules.LuaBehaviour
---@field Finish                            UnityEngine.RectTransform
---@field TextTime                        UnityEngine.RectTransform
---@field GoodNode                        UnityEngine.RectTransform
---@field UIFX_UnReceived                UnityEngine.RectTransform
---@field ImgBg                            UnityEngine.RectTransform
local UIActivityEntryWelfareCellNode = Class('UIActivityEntryWelfareCellNode')

function UIActivityEntryWelfareCellNode:__init()
    self.data = nil
    self.cb = nil
    self.position = 0
    self.specialRewardEffectTrans = nil
end

function UIActivityEntryWelfareCellNode:__delete()
    self.data = nil
    self.cb = nil
    self.position = 0
    self.specialRewardEffectTrans = nil
end

function UIActivityEntryWelfareCellNode:Awake()
    self.specialRewardEffectTrans = self.controller.transform:Find("UIFX_SpecialReward")
    SetButtonAction(self.controller.gameObject, function()
        if self.cb then
            self.cb(self.data)
        end
    end)
end

---FreshUI
---@param data table
---@param callBack function
---@param position number 位置
---@param alreadyDrawNum number 当前已领取的天数
function UIActivityEntryWelfareCellNode:FreshUI(data, callBack, position, alreadyDrawNum, drawStatus)
    self.data = data
    self.cb = callBack
    self.position = position
    CfUtils.SetActive(self.Finish, position <= alreadyDrawNum)
    CfUtils.FillText(self.TextTime, localize('第_num_天', { _num_ = position }))
    CfUtils.SetActive(self.controller.transform:Find("UIFX_SuperReward"), false)
    if table.indexof(Days, position) then
        CfUtils.SetUISwitchImage(self.ImgBg, 2)
        CfUtils.SetUISwitchText(self.TextTime, 2)
        if position > alreadyDrawNum then
            CfUtils.SetActive(self.controller.transform:Find("UIFX_SuperReward"), true)
        else
            CfUtils.SetActive(self.controller.transform:Find("UIFX_SuperReward"), false)
        end
    else
        CfUtils.SetUISwitchImage(self.ImgBg, 1)
        CfUtils.SetUISwitchText(self.TextTime, 1)
    end
    if drawStatus == 0 and position == (alreadyDrawNum + 1) then
        CfUtils.SetActive(self.UIFX_UnReceived, true)
    else
        CfUtils.SetActive(self.UIFX_UnReceived, false)
    end
    CfUtils.SetActive(self.specialRewardEffectTrans, checkInt(data.effects) == 1 and position > alreadyDrawNum)
    local env = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodeMBPath)
    if not isNull(env) then
        local reward = table.takeFirst(data.rewards)
        local goodsId = reward.goodsId
        env:Reload({
            goodsId = goodsId,
            isShowNo = true,
            text = 'x' .. GoodsUtils.GetGoodsText(goodsId, reward.num, 2)
        })
        env:SetClickCallback(function()
            if self.cb then
                self.cb(self.data , self.controller)
            end
            --local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            --GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end)

        -- self.TxtNumber.text = GoodsUtils.GetGoodsText(goodsId, reward.goodsNum, 3)
    end
end

function UIActivityEntryWelfareCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityEntryWelfareCellNode